var BrowserDetect = {
    init: function () {
        this.browser = this.searchString(this.dataBrowser) || "An unknown browser";
        this.version = this.searchVersion(navigator.userAgent)
			|| this.searchVersion(navigator.appVersion)
			|| "an unknown version";
        this.OS = this.searchString(this.dataOS) || "an unknown OS";
    },
    searchString: function (data) {
        for (var i = 0; i < data.length; i++) {
            var dataString = data[i].string;
            var dataProp = data[i].prop;
            this.versionSearchString = data[i].versionSearch || data[i].identity;
            if (dataString) {
                if (dataString.indexOf(data[i].subString) != -1)
                    return data[i].identity;
            }
            else if (dataProp)
                return data[i].identity;
        }
    },
    searchVersion: function (dataString) {
        var index = dataString.indexOf(this.versionSearchString);
        if (index == -1) return;
        return parseFloat(dataString.substring(index + this.versionSearchString.length + 1));
    },
    dataBrowser: [
		{
		    string: navigator.userAgent,
		    subString: "Chrome",
		    identity: "Chrome"
		},
		{
		    string: navigator.userAgent,
		    subString: "OmniWeb",
		    versionSearch: "OmniWeb/",
		    identity: "OmniWeb"
		},
		{
		    string: navigator.vendor,
		    subString: "Apple",
		    identity: "Safari",
		    versionSearch: "Version"
		},
		{
		    prop: window.opera,
		    identity: "Opera",
		    versionSearch: "Version"
		},
		{
		    string: navigator.vendor,
		    subString: "iCab",
		    identity: "iCab"
		},
		{
		    string: navigator.vendor,
		    subString: "KDE",
		    identity: "Konqueror"
		},
		{
		    string: navigator.userAgent,
		    subString: "Firefox",
		    identity: "Firefox"
		},
		{
		    string: navigator.vendor,
		    subString: "Camino",
		    identity: "Camino"
		},
		{		// for newer Netscapes (6+)
		    string: navigator.userAgent,
		    subString: "Netscape",
		    identity: "Netscape"
		},
		{
		    string: navigator.userAgent,
		    subString: "MSIE",
		    identity: "Explorer",
		    versionSearch: "MSIE"
		},
		{
		    string: navigator.userAgent,
		    subString: "Gecko",
		    identity: "Mozilla",
		    versionSearch: "rv"
		},
		{ 		// for older Netscapes (4-)
		    string: navigator.userAgent,
		    subString: "Mozilla",
		    identity: "Netscape",
		    versionSearch: "Mozilla"
		}
    ],
    dataOS: [
		{
		    string: navigator.platform,
		    subString: "Win",
		    identity: "Windows"
		},
		{
		    string: navigator.platform,
		    subString: "Mac",
		    identity: "Mac"
		},
		{
		    string: navigator.userAgent,
		    subString: "iPhone",
		    identity: "iPhone/iPod"
		},
		{
		    string: navigator.platform,
		    subString: "Linux",
		    identity: "Linux"
		}
    ]

};
BrowserDetect.init();

jQuery.browser = {};
jQuery.browser.mozilla = (BrowserDetect.browser == 'Firefox' || BrowserDetect.browser == 'Mozilla' || BrowserDetect.browser == 'Netscape');
jQuery.browser.webkit = (BrowserDetect.browser == 'Chrome');
jQuery.browser.opera = (BrowserDetect.browser == 'Opera')
jQuery.browser.msie = (BrowserDetect.browser == 'Explorer')

jQuery.browser.version = BrowserDetect.version;

if (!window.console) {
    window.console = {
        log: function (obj) { /* define own logging function here, or leave empty */ }
    };
}
if (!window.console.debug) {
   window.console.debug = function(obj) {};
};

if (!String.prototype.trim) {
    String.prototype.trim = function () { return this.replace(/^\s+|\s+$/g, ''); };
}
if (typeof String.prototype.startsWith != 'function') {
  // see below for better implementation!
  String.prototype.startsWith = function (str){
    return this.indexOf(str) == 0;
  };
}

if (!Date.prototype.toISOString) {
  (function() {

    function pad(number) {
      if (number < 10) {
        return '0' + number;
      }
      return number;
    }

    Date.prototype.toISOString = function() {
      return this.getUTCFullYear() +
        '-' + pad(this.getUTCMonth() + 1) +
        '-' + pad(this.getUTCDate()) +
        'T' + pad(this.getUTCHours()) +
        ':' + pad(this.getUTCMinutes()) +
        ':' + pad(this.getUTCSeconds()) +
        '.' + (this.getUTCMilliseconds() / 1000).toFixed(3).slice(2, 5) +
        'Z';
    };

  }());
}
function useTimezone(dateStr,format) {
    if (format==undefined || format==null) {
        format = 'dd.MM.yyyy HH:mm:ss';
    }
   var dd = kendo.parseDate(dateStr,'dd.MM.yyyy HH:mm:ss');
   if (dd==null)
       return null;
   var newDD = kendo.parseDate(dd.toISOString().split('.')[0]);
   if (newDD==null)
       return null;
   // var cd = kendo.parseDate(dd,'dd.MM.yyyy HH:mm:ss');
   return kendo.toString(newDD,format);
}
var tryParseJson = function (str){
    try {
        var jsonData = JSON && JSON.parse(str) || $.parseJSON(str);
        return jsonData;
    } catch (e) {
        return null;
    }
};
var tryParseDate = function (strDate){
    var dl = null;
    try{
        var dateParts = strDate.split(".");
        dl = new Date(dateParts[2], ( parseInt(dateParts[1]) - 1), dateParts[0]);
        
        if ( Object.prototype.toString.call(dl) === "[object Date]" ) {
            if ( isNaN( dl.getTime() ) ) {  // d.valueOf() could also work
              dl=null;
            }
        } else {
          dl = null;
        }
    } catch (e) {
        dl = null;
    }    
    return dl;
};


function isEqual(a, b) {
    // Create arrays of property names
    var aProps = Object.getOwnPropertyNames(a);
    var bProps = Object.getOwnPropertyNames(b);

    // If number of properties is different,
    // objects are not equivalent
    if (aProps.length != bProps.length) {
        return false;
    }

    for (var i = 0; i < aProps.length; i++) {
        var propName = aProps[i];

        // If values of same property are not equal,
        // objects are not equivalent
        if (a[propName] !== b[propName]) {
            return false;
        }
    }

    // If we made it this far, objects
    // are considered equivalent
    return true;
}


var setHref=function(data) {
    var frm = $('<form method="get" action="index.php" />');
    if (data.reload) {
        $.each(data.reload, function(i, val) {
            frm.append('<input type="hidden" name="'+ val.key +'" value="'+ val.value +'" />');
        });
    }
    $('#container').append(frm);
    frm.submit();
}


function imposeMaxLength(comp, MaxLen) {
    var left = parseInt(MaxLen) - comp.value.length;
    $(comp).parent().find('.addit').html('Chars left: <strong><b>' + left + '<\/strong>');
    return (comp.value.length <= MaxLen);
}

function readableFileSize(size) {
    var units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    var i = 0;
    while(size >= 1024) {
        size /= 1024;
        ++i;
    }
    return size.toFixed(1) + ' ' + units[i];
}

