// invalid
(function ($){
    $.fn.invalid = function () {
       
        if (!this) return;
        var me = $(this);
        var element = me;
        if (me.data('role')=='dropdownlist') {
            element = me.closest('span').find('.k-dropdown-wrap');
        }
        element.scrollintoview({
            duration: 500,
            direction: "both",
            complete: function() {
                element.css('background-color', '#FF0000');
                element.stop().animate({
                    backgroundColor: "#FFFFFF"
                }, 1000, function() {
                    element.css('background-color', '');
                });
            }
        });
            
        return this;
    };
})(jQuery);


function Message(type,title,message) {    
    if (type==='info') {
        $.growlUI(title, message); 
        return;
    }
    var wrapper = $('.sirius-message');
    $.blockUI();
    if (wrapper.length===0) {
        wrapper = $('<div class="sirius-message" ><div><h2></h2><p></p></div><input type="button" value="Back" class="k-button message-backbutton" />');
        $('body').append(wrapper);
    }
    wrapper.removeClass('error').removeClass('info');
    var titleEl = wrapper.find('h2');
    var messageEl = wrapper.find('p');
    var messageWrap = $(wrapper.children()[0]);
    var ReturnButton = wrapper.find('.message-backbutton');
    ReturnButton.unbind( "click" );
    ReturnButton.click(function(e) {
       e.preventDefault();
       close();   
    });
            
    var types = {
        error: {
            class: "err_none",
            wrapClass: "error"       
        },
        info: {
            class: "info_none",
            wrapClass: "info"
        },
        security: {
            class: "err_security",
            wrapClass: "error"
        }
    };
    
    var currentType = types[type];
    messageWrap.attr('class',currentType.class);
    wrapper.addClass(currentType.wrapClass);
    
    
    
    titleEl.html(title);
    messageEl.html(message);
    
    var topMargin = -1 * wrapper.height()/2;
    
    
    wrapper.css({'top':'-500px','opacity':'0'});
    
    var open = function() {
        wrapper.stop(true,false).animate({
            opacity: 1,
            top: '50%',
            marginTop: topMargin
        }, 500, 'easeOutExpo');
    };
    
    var close = function() {
        wrapper.stop(true,false).animate({
            opacity: 0,
            top: '-300px'
        }, 500, 'easeInExpo', function () {
            ReturnButton.unbind( "click" );
            wrapper.remove();
            $.unblockUI();
        });
        
    };
    
    open();
    return this;
}



function KendoErrorHandler(e) {
    console.log(e);
    var error = String(e.errorThrown);
    var data = {
        type: (error==='Forbidden' || error==='Unauthorized')?'security':'error',
        title: error,
        error: 'Unknown error'
    };
    if (e.status === 'parsererror') {
        data.error = 'Requested JSON parse failed.';
    } else if (e.status === 'timeout') {
        data.error = 'Request timed out.';
    } else if (e.status === 'abort') {
        data.error = 'Request aborted.';
    } else {
        if (e.xhr.responseText!=='') {
            data.error = e.xhr.responseText;
            var jsonData = tryParseJson(e.xhr.responseText);
            if (jsonData!==null) {
                if (jsonData.invalids) {
                    data.invalids = jsonData.invalids;
                }
                data.error = jsonData.error;
                data.title = jsonData.title;
            }
        }
    }
    if (data.invalids) {
        $('#'+data.invalids[0]).invalid();
        return;
    }
    Message(data.type,data.title,data.error);
    
    /*
    var data = tryParseJson(e.xhr.responseText);
    var errType = '';
    var errTitle = '';
    if ((typeof e.errorThrown)==='string') {
         errType = (e.errorThrown==='Forbidden' || e.errorThrown==='Unauthorized')?'security':'error';
         errTitle = e.errorThrown;
    } else {
        errType = 'error';
        errTitle = e.errorThrown.message;
    }
    if (e.status === 'parsererror') {
        errTitle = 'Requested JSON parse failed.';
    }
    if (data===null) {
        Message(errType,errTitle,e.xhr.responseText);
    } else {
        if (data.invalids) {
            $('#'+data.invalids[0]).invalid();
            return;
        }
        Message(errType,data.title,data.error);
    }
    */
}

function AjaxErrorHandler(xhr, status, error) {
    console.log(xhr);
    error = String(error);
     var data = {
        type: (error==='Forbidden' || error==='Unauthorized')?'security':'error',
        title: error,
        error: 'Unknown error'
    };
   

    if (status === 'parsererror') {
        data.error = 'Requested JSON parse failed.';
    } else if (status === 'timeout') {
        data.error = 'Request timed out.';
    } else if (status === 'abort') {
        data.error = 'Request aborted.';
    } else {
        if (xhr.responseText!=='') {
            data.error = xhr.responseText;
            var jsonData = tryParseJson(xhr.responseText);
            if (jsonData!==null) {
                if (jsonData.invalids) {
                    data.invalids = jsonData.invalids;
                }
                data.error = jsonData.error;
                data.title = jsonData.title;
            }
        }
    }
    return data;        
}



var makeRequest = function(options) {
    var settings = $.extend({
            url: 'index.php',
            method: 'POST',
            dataType: 'json',
            data: { response: 'json' },
            onSuccess: function(data,status) { },
            onError: function(error,responseText) { return true; },
            wrapper: '#content',
            loading: 'imgs/loading.gif',
            showSuccess: false,
            SuccessMessage: ''
        }, options, true );
    var PageWrapper = settings.wrapper!==''?$(settings.wrapper):null;
    
    if (PageWrapper!==null) PageWrapper.block({message: '<img src="'+ settings.loading + '" />'});
    $.post(settings.url, settings.data, function(data) {
        if (PageWrapper!==null) PageWrapper.unblock();
        if (settings.onSuccess(data,'OK')==false) 
           return;
        if (data.reload) {
            var frm = $('<form method="get" action="index.php" />');
            $.each(data.reload, function(i, val) {
                frm.append('<input type="hidden" name="'+ val.key +'" value="'+ val.value +'" />');
            });
            if (PageWrapper!==null) {
                PageWrapper.append(frm);
            } else {
                $('body').append(frm);
            }
            frm.submit();
        } else {
            if (settings.showSuccess)
                Message('info','Ok',settings.SuccessMessage); 
        }
    }, settings.dataType).error(
            function(xhr, status, error) {
                if (PageWrapper!==null) PageWrapper.unblock();
                var data = AjaxErrorHandler(xhr,status,error);
                if (settings.onError(data,error)==false) 
                    return;
                if (data.invalids) {
                    $('#'+data.invalids[0]).invalid();
                    return;
                } else {
                    Message(data.type,data.title,data.error);
                }
            });
    return true;
};

// urlbuilder 
(function ($){
    $.fn.urlbuilder = function (options) {
        // {bind : '#fromname', url : 'translit.php'}
        
        var settings = $.extend({
            // These are the defaults.
            bind: '#fromname',
            alias: '',
            parentid: '',
            itemtype: '',
            url: 'helpers/urlbuilder.cmd',
            field:'',
            delay: 300
        }, options );
        
        var me = $(this);
        var source = $(settings.bind);
        var target = $(settings.field);
        
        
        var search = function() {
            var _alias = $(settings.alias).val();
			var _itemType = settings.itemtype;
            if (settings.itemtype.startsWith('#')) {
                _itemType =  $(settings.itemtype).val();
            }
            var _parent_id  = settings.parentid;
            if (settings.parentid.startsWith('#')) {
                _parent_id =  $(settings.parentid).val();
            }
            
            $.post(settings.url,{ response : 'json', mode: settings.mode, itemtype: settings.itemtype, alias: _alias, parent_id: _parent_id},
                function(data) {
                    if (data.url) {
                        target.val(data.url);
                    } else {
                        target.val('');
                    }
                    me.css('color','').html(data.url);
                }, 'json').error(
                function(xhr, status, error)  { 
                    var data = AjaxErrorHandler(xhr,status,error);
                    me.css('color','red').html(data.error);
                });
        };
        
        source.bind("change paste keyup", function() {
            clearTimeout($.data(this, 'timer'));
            var wait = setTimeout(search, settings.delay);
            $(this).data('timer', wait);
        });
            
        
        return this;
    };
})(jQuery);


// myform
(function ($){
    $.fn.myForm = function (options) {
      
        var settings = $.extend({
            data: { response: 'json' },
            onSuccess: function(data,status) { return true; },
            onError: function(error,responseText) { return true; },
            beforeSubmit: function(arr, form, options) { return true; },
            uploadProgress: function(event,position,total,percentComplete) { },
            wrapper: '#content',
            showSuccess: true,
            SuccessMessage: 'Saved'
        }, options );
        
        var me = $(this);
        
        
        var PageWrapper = $(settings.wrapper);
        
        
        CKupdate = function(){
            if (typeof(CKEDITOR) != 'undefined') {
                for ( instance in CKEDITOR.instances )
                    CKEDITOR.instances[instance].updateElement();
            }
        };        
        
        
        
        var formOptions = {
            data: settings.data,
            dataType: 'json',
            clearForm: false,
            resetForm: false,
            beforeSerialize: function() { 
                CKupdate();
            },
            beforeSubmit: function(arr, form, options) {
                if (settings.beforeSubmit(arr, form, options) === false) return false;
                PageWrapper.block({message: '<img src="imgs/loading.gif" />'});
                return true;
            },  
            success: function(data,status) {
                PageWrapper.unblock();
                me.find('input[type="file"]').val("");
                if (settings.onSuccess(data,status)===false) 
                   return;
                if (data.reload) {
                    var frm = $('<form method="get" action="index.php" />');
                    $.each(data.reload, function(i, val) {
                        frm.append('<input type="hidden" name="'+ val.key +'" value="'+ val.value +'" />')
                    });
                    $(settings.wrapper).append(frm);
                    frm.submit();
                } else {
                    if (settings.showSuccess)
                        Message('info','Ok',settings.SuccessMessage); 
                }
            },
            error: function(xhr, status, error) {
               
                PageWrapper.unblock();
                var data = AjaxErrorHandler(xhr,status,error);
                if (settings.onError(data,error)==false) 
                    return;
                if (data.invalids) {
                    $('#'+data.invalids[0]).invalid();
                    return;
                } else {
                    Message(data.type,data.title,data.error);
                }
            },
            uploadProgress: function(event,position,total,percentComplete) { }
        };
        
        $(this).ajaxForm(formOptions);
        
        
        return this;
    };
})(jQuery);


function redirectTo(data) {
    var frm = $('<form method="get" action="index.php" />');
    $.each(data, function(i, val) {
        frm.append('<input type="hidden" name="'+ val.key +'" value="'+ val.value +'" />')
    });
    $('body').append(frm);
    frm.submit();
}